import {initialState} from './store.js';
import {exercises,equipmentLabels} from './data.js';
const ids=new Set(exercises.map(e=>e.id));
function fail(message){throw new Error(message)}
export function validDate(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+'T12:00:00Z');return !Number.isNaN(d.getTime())&&d.toISOString().slice(0,10)===v}
function number(v,min,max,label,nullable=false,integer=false){if(nullable&&(v===null||v===undefined))return;if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max||(integer&&!Number.isInteger(v)))fail(label+' is outside the allowed range.')}
function text(v,max,label){if(typeof v!=='string'||v.length>max)fail(label+' is invalid or too long.')}
function id(v){if(typeof v!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(v))fail('Invalid record identifier.')}
function record(r,collection){if(!r||typeof r!=='object'||Array.isArray(r))fail('Invalid '+collection+' record.');id(r.id);if(!validDate(r.date))fail('Invalid date in '+collection+'.')}
function noDangerousKeys(v){if(v&&typeof v==='object'){for(const key of Object.keys(v)){if(['__proto__','prototype','constructor'].includes(key))fail('Unsafe backup key.');noDangerousKeys(v[key])}}}
export function validateDraft(d){id(d.id);text(d.name,100,'Workout name');if(!validDate(d.date))fail('Choose a valid workout date.');if(!Array.isArray(d.exercises)||d.exercises.length>100)fail('Invalid workout exercises.');for(const e of d.exercises){id(e.id);if(!ids.has(e.exerciseId))fail('Unknown exercise identifier: '+e.exerciseId);if(!Array.isArray(e.sets)||e.sets.length>100)fail('Too many sets.');text(e.notes||'',500,'Exercise note');text(e.superset||'',30,'Superset label');for(const s of e.sets){id(s.id);number(s.load,0,1000,'Set load',true);number(s.reps,0,1000,'Repetitions',true,true);number(s.duration,0,86400,'Set duration',true);number(s.distance,0,100000,'Set distance',true);number(s.rpe,1,10,'RPE',true);number(s.rir,0,10,'RIR',true);if(typeof s.done!=='boolean'||typeof s.warmup!=='boolean')fail('Invalid set status.');if(s.done&&!(s.reps>0||s.duration>0||s.distance>0))fail('A completed set needs repetitions, duration, or distance.');if(s.rpe>=8&&s.rir!==null&&s.rir!==undefined&&Math.abs(s.rpe+s.rir-10)>.5)fail('RPE and RIR conflict. For RPE 8–10, the RIR convention is approximately 10 minus RPE.')}}text(d.notes||'',1000,'Session notes');number(d.restSeconds??120,0,1800,'Rest time');return d}
export function validateState(input){noDangerousKeys(input);if(!input||input.version!==1)fail('Unsupported backup version.');const rootKeys=Object.keys(initialState());if(Object.keys(input).some(k=>!rootKeys.includes(k)))fail('Unexpected backup field.');const s={...initialState(),...input,profile:{...initialState().profile,...input.profile}};const p=s.profile;text(p.name,100,'Name');number(p.age,18,100,'Age',true,true);number(p.height,100,250,'Height',true);number(p.weight,25,400,'Profile weight',true);number(p.targetWeight,25,400,'Target weight',true);number(p.calorieTarget,500,10000,'Daily calorie target',false,true);number(p.activity,1.1,2.5,'Activity factor');number(p.measuredTdee,500,10000,'Maintenance estimate',true);number(p.hrmax,80,250,'HRmax',true);number(p.activityGoal,30,1000,'Activity goal');number(p.recoveryHours,24,168,'Recovery display window');number(p.days,1,7,'Training days',false,true);text(p.limitations||'',1000,'Limitations');if(!['male','female',''].includes(p.sex)||!['metric','imperial'].includes(p.units)||!['dark','light'].includes(p.theme)||!['beginner','intermediate','advanced'].includes(p.experience)||!['fat-loss','maintenance','muscle-growth','strength','endurance','general','recomposition','mobility'].includes(p.goal))fail('Invalid profile option.');if(!Array.isArray(p.equipment)||p.equipment.some(e=>!equipmentLabels[e]))fail('Unknown equipment.');if(typeof p.trackWellbeing!=='boolean')fail('Invalid tracking preference.');for(const collection of rootKeys.filter(k=>!['version','profile','draft'].includes(k))){if(!Array.isArray(s[collection])||s[collection].length>100000)fail('Invalid '+collection+' collection.');if(collection==='calorieDays'){if(s[collection].some(d=>!validDate(d))||new Set(s[collection]).size!==s[collection].length)fail('Invalid complete calorie days.');continue}const unique=new Set();for(const r of s[collection]){id(r.id);if(unique.has(r.id))fail('Duplicate identifier in '+collection);unique.add(r.id);if(collection!=='routines')record(r,collection)}}
for(const c of s.calories){number(c.kcal,1,20000,'Calories',false,true);text(c.description,160,'Calorie description')}
for(const w of s.weights){number(w.kg,25,400,'Weight');text(w.note||'',300,'Weight note')}if(new Set(s.weights.map(x=>x.date)).size!==s.weights.length)fail('Only one weigh-in per date is supported.');
for(const m of s.measurements){for(const k of ['waist','hips','chest','arm','thigh','neck'])number(m[k],1,400,'Measurement',true);text(m.note||'',500,'Measurement note')}
for(const b of s.bodyfat){number(b.percentage,1,74,'Body fat');number(b.uncertainty,0,30,'Body-fat uncertainty',true);text(b.method,100,'Body-fat method');text(b.note||'',500,'Body-fat note')}
for(const p of s.photos){if(typeof p.data!=='string'||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.data)||p.data.length>6000000)fail('Invalid or oversized photo.');text(p.caption||'',300,'Photo caption')}
for(const s0 of s.sessions)validateDraft(s0);if(s.draft!==null)validateDraft(s.draft);
for(const r of s.routines){text(r.name,100,'Routine name');number(r.restSeconds,0,1800,'Routine rest');if(!Array.isArray(r.exercises)||!r.exercises.length||r.exercises.length>100)fail('Invalid routine exercises.');for(const e of r.exercises){if(!ids.has(e.exerciseId))fail('Unknown routine exercise.');number(e.sets,1,20,'Routine sets',false,true);number(e.reps,1,100,'Routine reps',false,true)}}
for(const x of s.schedule){if(!s.routines.some(r=>r.id===x.routineId))fail('Schedule refers to a missing routine.')}
for(const c of s.cardio){text(c.type,100,'Activity type');number(c.duration,1,1440,'Activity duration');number(c.distance,0,1000,'Activity distance',true);number(c.hr,30,250,'Heart rate',true);number(c.met,1,25,'MET',true);text(c.note||'',500,'Activity note');if(!['light','moderate','vigorous'].includes(c.intensity))fail('Invalid activity intensity.')}
for(const w of s.wellbeing){number(w.sleep,0,24,'Sleep duration',true);number(w.steps,0,200000,'Steps',true,true);for(const key of ['energy','soreness','recovery'])number(w[key],1,5,key,true,true);text(w.note||'',500,'Recovery note')}if(new Set(s.wellbeing.map(x=>x.date)).size!==s.wellbeing.length)fail('Only one recovery record per date is supported.');return s}
